+          <button type="submit">Search</button>
+        </form>
+      </header>
+      <section className="filters" aria-label="Prompt filters">
+        <button className={!search.model || search.model === 'all' ? 'active' : ''} onClick={() => apply({ model: 'all' })}>All</button>
